zh: {
  meta_title: 'Nong Khiaw Eco-Trail | 老挝南凯云海露营与徒步行程',
  meta_desc: '老挝南凯（Nong Khiaw）云海之上露营、2日及3日徒步、家庭住宿、皮划艇和一日船游。本地团队自2024年起运营。到店付款，WhatsApp预订。',
  nav_tour: '行程',
  lead: '由当地人带队的行程。徒步登上云海之上的营地，在星空下入睡，乘慢船沿乌江而上，再划皮划艇穿过群山返回。',
  cta_see: '查看全部行程',
  f2s: '30美元起', f2l: '每人', f3s: '4条行程', f3l: '1至3天',
  tours_tag: '我们的行程', tours_h: '选择你的冒险。',
  tours_sub: '四种方式游览南凯，均配英语本地向导。到店付款。',
  pkg: '套餐', code_day: '行程编号 001',
  lvl_mod: '中等', lvl_easy: '轻松',
  dur_1d: '1天', dur_1n: '2天1晚', dur_2n: '3天2晚',
  see_plan: '查看行程安排', book_this: '预订此行程',
  d1l: '第1天', d2l: '第2天', d3l: '第3天',
  p101_t: '云海之上过夜露营', p101_s: '徒步前往360°观景台，在云海之上的帐篷中过夜，欣赏日落与日出。往返乘慢船。',
  p102_t: '2天1晚：露营加全天探险', p102_s: '先在云海之上露营，再享一整天行程：克木族村庄、瀑布、有机农场、孟威洞穴与观景台，最后划皮划艇返回。',
  p103_t: '3天2晚：露营、家庭住宿与探险', p103_s: '云海之上露营，游览瀑布与孟威，在村里家庭住宿一晚，丛林徒步，并划皮划艇顺乌江而下。',
  camp_d1: '下午2:30在我们位于 The Trio Bar & Cafe 内的办公室集合。乘慢船逆流到当地村庄，探访稻田与村庄生活，再徒步约2.5小时到云海之上的营地。帐篷、厕所、篝火、烧烤晚餐、日落与星空。',
  p101_d2: '起床看日出、吃早餐，然后下山徒步40至50分钟，途经村庄与季节性稻田。乘慢船返回南凯（约上午9:00至9:30）。',
  p102_d2: '看日出、吃早餐，然后下山步行约1.5小时到河边。约上午9:00船来接：逆流到索孔，参观克木族村庄与瀑布，在有机农场用午餐，游览孟威洞穴与观景台，再划皮划艇顺流回南凯。约下午4:30至5:30结束。',
  p103_d2: '早餐后乘慢船逆流到索孔。参观塔莫瀑布和有机农场，继续前往孟威，游览村庄、观景台与洞穴。傍晚前往索占村，体验传统家庭住宿。',
  p103_d3: '早餐后进行3至4小时的丛林徒步。午餐后划皮划艇顺乌江返回南凯。返回琅勃拉邦，送到住宿处或市中心（约下午3:00至4:30）。',
  p102_note: '第2晚在南凯的住宿不含。次日上午10:30有小巴返回琅勃拉邦。',
  inc_camp: '英语本地向导 · 帐篷、睡垫和毯子 · 一大瓶水',
  inc_101: '餐食：晚餐（第1天），早餐（第2天）',
  inc_102: '餐食：晚餐（第1天），早餐和午餐（第2天）',
  inc_103: '英语本地向导 · 慢船 · 所有门票 · 每人3瓶水。餐食：第1天晚餐；第2天早餐、午餐和晚餐；第3天早餐和午餐',
  br_camp: '小背包、舒适的登山鞋、外套或保暖衣物（夜间和清晨很冷）、头灯、驱蚊液、相机',
  br_103: '轻装出行：小背包、登山鞋、凉鞋、保暖衣物、头灯、驱蚊液、泳衣、换洗衣物、相机',
  opt_massage: '可选：徒步后可安排老挝按摩（不含在价格内）。',
  info_tag: '预订前', info_h: '须知',
  inf1h: '到店付款', inf1p: '在我们位于 The Trio Bar & Cafe 内的办公室付款。接受基普或美元，现金或刷卡（刷卡收3%银行手续费）。',
  inf2h: '琅勃拉邦接送', inf2p: '不含，但可代为安排：每人单程200,000基普，往返400,000基普。上午7:30至8:00在酒店接。返程小巴10:30出发。请提前2至3天预订。',
  inf3h: '大件行李可寄存', inf3p: '行程期间可把行李放在我们办公室，只带一个小背包。',
  inf4h: '餐食', inf4p: '如果您吃素或有过敏，请告诉我们。从琅勃拉邦出发当天，请自带三明治或零食作午餐。',
  inf5h: '团队', inf5p: '拼团出行。有时超过10人，有时更少。每个套餐露营的观景台不同。',
  office_h: '集合地点', office_p: '我们的办公室在南凯 The Trio Bar & Cafe 内。', office_map: '在谷歌地图中打开定位',
  review_link: '查看我们的谷歌评价',
  lbl_tour: '行程', tour_101: '101 · 过夜露营（30美元）', tour_102: '102 · 2天1晚（60美元）', tour_103: '103 · 3天2晚（90美元）', tour_001: '001 · 一日船游（30美元）',
  lbl_food: '餐食', food_reg: '普通', food_veg: '素食',
  lbl_transfer: '琅勃拉邦接送', tr_none: '不需要', tr_round: '往返（400,000基普）',
  book_tag: '预订您的行程', book_p: '填写简短表单，WhatsApp 会带着您的消息打开。在 WhatsApp 中点击发送之前不会发出任何内容。到店当面付款。',
  q1: '行程多少钱？', a1: '每人：过夜露营（101）30美元，2天1晚（102）60美元，3天2晚（103）90美元，一日船游（001）30美元。',
  q2: '行程几点开始？', a2: '露营行程约下午2:00至2:30在 The Trio Bar & Cafe 内的办公室开始。一日船游上午8:30开始。',
  q3: '包含什么？', a3: '英语本地向导、露营装备（帐篷、睡垫、毯子）、饮用水和各行程所列餐食。3日行程和一日游含门票。',
  q4: '可以吃素吗？', a4: '可以。预订时告诉我们您吃素或有食物过敏即可。',
  q5: '需要带什么？', a5: '小背包、舒适的登山鞋、保暖衣物、头灯、驱蚊液和相机。雨季请带雨具。3日行程另需泳衣和凉鞋。',
  q6: '如何预订和付款？', a6: '通过 WhatsApp +856 20 5897 5057 联系我们，或使用下方表单。到达后在办公室当面付款（基普或美元，现金或刷卡，刷卡收3%手续费）。',
  q7: '包含琅勃拉邦的交通吗？', a7: '不含，但可代为安排，每人单程200,000基普。上午7:30至8:00酒店接，返程小巴10:30从南凯出发。',
  q8: '需要自带帐篷吗？', a8: '不需要。我们提供帐篷、睡垫和毯子。营地有简易当地式厕所，没有淋浴。',
  q9: '行李可以寄存在哪里？', a9: '放在我们位于 The Trio Bar & Cafe 的办公室，行程期间免费。',
  trav: '旅客', trav_p: '请为团里每一位填写，与护照上一致。',
  lbl_fullname: '姓名（与护照一致）', lbl_gender: '性别', g_sel: '请选择…', g_f: '女', g_m: '男', g_x: 'X / 其他',
  lbl_nat: '国籍', ph_nat: '例如：德国', lbl_pass: '护照号码', lbl_issue: '签发日期', lbl_expiry: '有效期至',
  lbl_hotel: '琅勃拉邦住宿', ph_hotel: '酒店或青旅名称',
  lbl_map: '住宿的 Google 地图链接', map_help: '打开 Google 地图，找到您的住宿，点击“分享” › “复制链接”，然后粘贴到这里。',
  btn_findmap: '在 Google 地图中查找', btn_paste: '粘贴链接', map_ok: '✓ 在 Google 地图上查看位置', paste_fail: '无法读取剪贴板。请长按输入框并粘贴。', tr_one: '单程至南凯（200,000基普）',
  ph_note: '过敏、带小孩、其他问题……',
  hint: '请填写日期以及每位旅客的信息。', hint_hotel: '请告诉我们您在琅勃拉邦的住宿，方便接送。', hint_map: '请粘贴住宿的 Google 地图链接。'
},

